fastify.get('/', { preHandler: fastify.requireAuth }, async (request, reply) => {
  if (!hasPermission(request.session.userId, 'ticket:create')) {
    return reply.redirect('/tickets');
  }

  return reply.view('index.ejs', viewData({
    user: request.user,
    agents: await listConfiguredAgentOptions(),
    agentGroups: await getTicketAssignableGroups(),
    agentGroupMembers: await getAgentGroupMembers(),
    workflows: await getEnabledWorkflows(),
    browserTargets: (await readBrowserTargets()).filter(target => target && target.status === 'active'),
    workTypes: (await readWorkTypes()).filter(workType => workType.status === 'active'),
    error: null
  }, request.session.userId));
});

// Shared ticket creation. Validates resolved inputs, builds the ticket with a
// normalized execution policy, persists it, emits ticket.created, and routes run
// creation through createRunsForTicket (which enforces the unresolved-triage block,
// the objective clarification/ambiguity gate, and the feasibility gate). Both the
// POST /tickets route and the process-template trigger use this; neither creates
// runs directly. `input` carries already-parsed values (objects, not form strings);
// transport-level JSON parsing stays in the HTTP layer. Returns { ok, ticket, runs }
// or { ok: false, error } so each caller can shape its own response.
async function createTicketFromInput(input, actor, options = {}) {
  const objective = typeof input.objective === 'string' ? input.objective.trim() : '';
  const assignmentTargetType = input.assignmentTargetType;

  if (!objective || !assignmentTargetType || input.assignmentTargetId == null || input.assignmentTargetId === '') {
    return { ok: false, error: 'Objective, assignment target type, and assignment target are required' };
  }

  const parsedAssignmentTargetId = parseInt(input.assignmentTargetId, 10);
  if (!['agent', 'group'].includes(assignmentTargetType) || Number.isNaN(parsedAssignmentTargetId)) {
    return { ok: false, error: 'Invalid assignment target' };
  }

  const resolvedAssignmentMode = assignmentTargetType === 'agent' ? 'individual' : input.assignmentMode;
  if (assignmentTargetType === 'group' && !['allocated', 'dynamic'].includes(resolvedAssignmentMode)) {
    return { ok: false, error: 'Group assignments require allocated or dynamic mode' };
  }
  let assignmentGroup = null;
  if (assignmentTargetType === 'agent' && !await getConfiguredAgentRepository().getConfiguredAgentById(parsedAssignmentTargetId)) {
    return { ok: false, error: 'Selected agent does not exist' };
  }
  if (assignmentTargetType === 'group') {
    assignmentGroup = (await getTicketAssignableGroups())
      .find(group => group.id === parsedAssignmentTargetId) || null;
    if (!assignmentGroup) {
      return { ok: false, error: 'Selected ticket-capable group does not exist' };
    }
  }

  const resolvedCapabilityType = input.capabilityType === 'workflow' || input.executionMode === 'workflow' ? 'workflow' : 'directAction';
  const resolvedExecutionMode = resolvedCapabilityType === 'workflow' ? 'workflow' : 'agent';
  let resolvedTargetRef = null;
  if (input.targetRef != null) {
    if (!input.targetRef || typeof input.targetRef !== 'object' || Array.isArray(input.targetRef) ||
        input.targetRef.kind !== 'browser' || typeof input.targetRef.browserTargetId !== 'string' ||
        !input.targetRef.browserTargetId.trim()) {
      return { ok: false, error: 'Browser target reference is invalid' };
    }
    if (resolvedExecutionMode === 'workflow') {
      return { ok: false, error: 'Workflow tickets cannot use browser targets' };
    }
    const browserTarget = (await getBrowserTargetById(input.targetRef.browserTargetId));
    if (!browserTarget || browserTarget.status !== 'active') {
      return { ok: false, error: 'Selected browser target does not exist or is inactive' };
    }
    resolvedTargetRef = { kind: 'browser', browserTargetId: browserTarget.id };
  }
  const targetKind = resolvedTargetRef ? 'browser' : 'workspace';
  const requestedWorkTypeId = typeof input.workTypeId === 'string' ? input.workTypeId.trim() : '';
  let selectedWorkType = null;
  if (requestedWorkTypeId) {
    selectedWorkType = (await getWorkTypeById(requestedWorkTypeId));
    if (!selectedWorkType) {
      return { ok: false, error: 'Selected Work Type does not exist' };
    }
    if (selectedWorkType.status !== 'active') {
      return { ok: false, error: 'Selected Work Type is inactive' };
    }
    if (!selectedWorkType.allowedTargetKinds.includes(targetKind)) {
      return { ok: false, error: `Selected Work Type is not compatible with ${targetKind} targets` };
    }
  }
  let selectedWorkflow = null;
  let parsedWorkflowInput = null;

  if (resolvedCapabilityType === 'workflow') {
    if (assignmentTargetType !== 'agent') {
      return { ok: false, error: 'Workflow tickets must be assigned to one agent' };
    }
    selectedWorkflow = await getWorkflowById(input.workflowId);
    if (!selectedWorkflow || selectedWorkflow.enabled === false) {
      return { ok: false, error: 'Selected workflow does not exist or is disabled' };
    }
    parsedWorkflowInput = input.workflowInput && typeof input.workflowInput === 'object' && !Array.isArray(input.workflowInput)
      ? input.workflowInput
      : {};
    const inputErrors = validateSchemaValue(selectedWorkflow.inputSchema || {}, parsedWorkflowInput, 'workflow.input');
    if (inputErrors.length > 0) {
      return { ok: false, error: `Workflow input invalid: ${inputErrors.join('; ')}` };
    }
  }

  let parsedOwnedPaths = input.ownedOutputPaths != null ? input.ownedOutputPaths : null;
  if (parsedOwnedPaths != null && (typeof parsedOwnedPaths !== 'object' || Array.isArray(parsedOwnedPaths))) {
    return { ok: false, error: 'Owned output paths must be a mapping of agent ID to path' };
  }

  // Work Context (r1.20) is OPTIONAL grouping. Validate the assignment up front (existence,
  // active status, allow-lists). This narrows — never widens — authority, and only labels the
  // ticket; the runtime never reads it. A null/absent context is always valid.
  const resolvedCapabilityIdForContext = selectedWorkflow ? selectedWorkflow.id : 'agent-selected-actions';
  const contextCheck = await validateWorkContextAssignment(input.workContextId, { capabilityId: resolvedCapabilityIdForContext, targetId: input.workContextTargetId });
  if (!contextCheck.ok) return { ok: false, error: contextCheck.error };

  const now = new Date().toISOString();
  const actorName = actor && actor.username
    ? actor.username
    : (actor && actor.userId != null ? String(actor.userId) : 'system');

  const acceptanceCriteria = typeof input.acceptanceCriteria === 'string' ? input.acceptanceCriteria.trim() : '';
  let newTicket = {
    objective,
    acceptanceCriteria: acceptanceCriteria || null,
    assignmentTargetType,
    assignmentTargetId: parsedAssignmentTargetId,
    assignmentMode: resolvedAssignmentMode,
    ownedOutputPaths: parsedOwnedPaths,
    targetRef: resolvedTargetRef,
    executionMode: resolvedExecutionMode,
    workflowId: selectedWorkflow ? selectedWorkflow.id : null,
    workflowInput: selectedWorkflow ? parsedWorkflowInput : null,
    capabilityType: resolvedCapabilityType,
    capabilityId: selectedWorkflow ? selectedWorkflow.id : 'agent-selected-actions',
    capabilityInput: selectedWorkflow ? parsedWorkflowInput : null,
    executionPolicy: normalizeExecutionPolicy(input.executionPolicy, resolvedAssignmentMode === 'individual' ? 'shared' : 'owned_paths'),
    workTypeId: selectedWorkType ? selectedWorkType.id : null,
    workTypeSnapshot: selectedWorkType ? snapshotWorkType(selectedWorkType, now) : null,
    status: 'open',
    createdBy: actorName,
    changedBy: actorName,
    changedAt: now,
    createdAt: now,
    updatedAt: now
  };
  // Optional provenance (e.g. process-template origin). Durable on the ticket;
  // normalizeTickets preserves unknown fields.
  if (options.source && typeof options.source === 'object') {
    newTicket.source = options.source;
  }
  if (typeof options.spawnIdempotencyKey === 'string' && options.spawnIdempotencyKey.trim()) {
    newTicket.spawnIdempotencyKey = options.spawnIdempotencyKey.trim();
  }
  // Optional Work Context grouping label + immutable snapshot (r1.20). Grouping/visibility
  // only — never read by the runtime. Contextless tickets simply omit these.
  if (contextCheck.context) {
    newTicket.workContextId = contextCheck.context.id;
    newTicket.workContextSnapshot = contextCheck.snapshot;
  }

  let assignedGroupAgents = [];
  if (assignmentTargetType === 'group') {
    try {
      assignedGroupAgents = await getAgentsInGroup(newTicket.assignmentTargetId);
      if (newTicket.assignmentMode === 'dynamic') {
        newTicket.ownedOutputPaths = deriveDynamicOwnedPaths(assignedGroupAgents);
      }
      if (usesOwnedScopeAllocation(newTicket)) {
        assertAllocatedTicketCanStart(newTicket, assignedGroupAgents);
      }
    } catch (error) {
      appendSystemLog('allocation:setup_failed', error.message, null, {
        code: error.code || (newTicket.assignmentMode === 'dynamic'
          ? 'DYNAMIC_ALLOCATION_ERROR'
          : 'VALIDATION_ERROR'),
        path: error.path || null,
        assignedAgentId: error.assignedAgentId || null,
        ticketId: newTicket.id || null,
        assignmentTargetId: newTicket.assignmentTargetId,
        createdBy: newTicket.createdBy
      });
      return { ok: false, error: error.message };
    }
  }

  let structuredAllocationAuthorityDraft = null;
  if (input.declaredWork !== undefined && input.declaredWork !== null) {
    try {
      if (!input.declaredWork || typeof input.declaredWork !== 'object' || Array.isArray(input.declaredWork)) {
        throw new TypeError('declaredWork must be a JSON object');
      }
      if (typeof input.declaredWork.objective !== 'string' ||
          input.declaredWork.objective.trim() !== objective) {
        throw new TypeError('declaredWork.objective must exactly match the ticket objective');
      }
      const plannerAgent = assignmentGroup && assignmentGroup.plannerAgentId != null
        ? await getConfiguredAgentRepository().getConfiguredAgentById(assignmentGroup.plannerAgentId)
        : null;
      structuredAllocationAuthorityDraft = buildStructuredAllocationAuthorityDraft({
        declaredWork: input.declaredWork,
        ticketObjective: objective,
        assignmentTargetType,
        assignmentMode: resolvedAssignmentMode,
        assignmentGroup,
        plannerAgent,
        candidateAgents: assignedGroupAgents,
        ownedOutputPaths: newTicket.ownedOutputPaths
      });
    } catch (error) {
      return { ok: false, error: error.message };
    }
  }

  try {
    const created = await getTicketRunLifecycleRepository().createTicketWithEvent({
      ticket: newTicket,
      structuredAllocationAuthorityDraft,
      eventPayload: {
        status: newTicket.status,
        assignmentTargetType: newTicket.assignmentTargetType,
        assignmentTargetId: newTicket.assignmentTargetId,
        assignmentMode: newTicket.assignmentMode,
        executionMode: newTicket.executionMode,
        capabilityType: newTicket.capabilityType,
        capabilityId: newTicket.capabilityId,
        workflowId: newTicket.workflowId,
        workTypeId: newTicket.workTypeId,
        workTypeSnapshot: copyWorkTypeSnapshot(newTicket.workTypeSnapshot),
        workTypeSnapshotSource: newTicket.workTypeSnapshot ? 'catalog_at_ticket_creation' : null,
        createdBy: newTicket.createdBy,
        ...(newTicket.source ? { source: newTicket.source.type } : {})
      }
    }, options.persistence || {});
    newTicket = created.ticket;
    options.ticketCreated = created.created !== false;
  } catch (error) {
    // Ticket creation and its required evidence are one PostgreSQL transaction.
    // A rejected event therefore leaves no partial ticket to compensate.
    throw error;
  }
  broadcastTicketChange();
  const runs = options.deferRunCreation === true
    ? [] : await createRunsForTicket(newTicket, options.delegated || null, options.persistence || {});

  return { ok: true, ticket: newTicket, runs, created: options.ticketCreated !== false };
}

fastify.post('/tickets', {
  preHandler: fastify.requireAuth,
  config: { mutationAdmission: true }
}, async (request, reply) => {
  if (!hasPermission(request.session.userId, 'ticket:create')) {
    reply.code(403);
    return 'Permission denied';
  }

  const { objective, assignmentTargetType, assignmentTargetId, assignmentMode, capabilityType, executionMode, workflowId, workflowInput, executionPolicy, executionTargetKind, browserTargetId, workTypeId, acceptanceCriteria, declaredWork } = request.body;

  async function renderTicketForm(error) {
    reply.code(400);
    return reply.view('index.ejs', viewData({
      user: request.user,
      agents: await listConfiguredAgentOptions(),
      agentGroups: await getTicketAssignableGroups(),
      agentGroupMembers: await getAgentGroupMembers(),
      workflows: await getEnabledWorkflows(),
      browserTargets: (await readBrowserTargets()).filter(target => target && target.status === 'active'),
      workTypes: (await readWorkTypes()).filter(workType => workType.status === 'active'),
      error
    }, request.session.userId));
  }

  // Transport-level JSON parsing (form fields arrive as strings). Semantic
  // validation and ticket construction live in the shared createTicketFromInput.
  const isWorkflowTicket = capabilityType === 'workflow' || executionMode === 'workflow';
  let parsedWorkflowInput = null;
  if (isWorkflowTicket) {
    try {
      parsedWorkflowInput = workflowInput && workflowInput.trim() ? JSON.parse(workflowInput) : {};
    } catch (error) {
      return await renderTicketForm('Workflow input must be valid JSON');
    }
    if (!parsedWorkflowInput || typeof parsedWorkflowInput !== 'object' || Array.isArray(parsedWorkflowInput)) {
      return await renderTicketForm('Workflow input must be a JSON object');
    }
  }

  let parsedDeclaredWork = null;
  if (typeof declaredWork === 'string' && declaredWork.trim()) {
    try {
      parsedDeclaredWork = JSON.parse(declaredWork);
    } catch (error) {
      return await renderTicketForm('Parent declared work must be valid JSON');
    }
    if (!parsedDeclaredWork || typeof parsedDeclaredWork !== 'object' || Array.isArray(parsedDeclaredWork)) {
      return await renderTicketForm('Parent declared work must be a JSON object');
    }
  } else if (declaredWork && typeof declaredWork === 'object' && !Array.isArray(declaredWork)) {
    parsedDeclaredWork = declaredWork;
  }

  let parsedOwnedPaths = null;
  if (request.body.ownedOutputPaths) {
    try {
      parsedOwnedPaths = JSON.parse(request.body.ownedOutputPaths);
    } catch (e) {
      return await renderTicketForm('Owned output paths must be valid JSON');
    }
  }

  let parsedExecutionPolicy = executionPolicy;
  if (typeof executionPolicy === 'string' && executionPolicy.trim()) {
    try {
      parsedExecutionPolicy = JSON.parse(executionPolicy);
    } catch (error) {
      return await renderTicketForm('Execution policy must be valid JSON');
    }
  }
  if (parsedExecutionPolicy !== undefined && parsedExecutionPolicy !== null &&
      (typeof parsedExecutionPolicy !== 'object' || Array.isArray(parsedExecutionPolicy))) {
    return await renderTicketForm('Execution policy must be a JSON object');
  }

  let parsedTargetRef = null;
  if (executionTargetKind === 'browser') {
    if (typeof browserTargetId !== 'string' || !browserTargetId.trim()) {
      return await renderTicketForm('Select an active browser target');
    }
    parsedTargetRef = { kind: 'browser', browserTargetId: browserTargetId.trim() };
  } else if (executionTargetKind && executionTargetKind !== 'workspace') {
    return await renderTicketForm('Execution target type must be workspace/filesystem or browser');
  } else {
    parsedTargetRef = request.body.targetRef;
  }
  if (typeof parsedTargetRef === 'string' && parsedTargetRef.trim()) {
    try {
      parsedTargetRef = JSON.parse(parsedTargetRef);
    } catch (error) {
      return await renderTicketForm('Browser target reference must be valid JSON');
    }
  }

  const result = await createTicketFromInput({
    objective,
    acceptanceCriteria,
    declaredWork: parsedDeclaredWork,
    assignmentTargetType,
    assignmentTargetId,
    assignmentMode,
    capabilityType,
    executionMode,
    workflowId,
    workflowInput: parsedWorkflowInput,
    ownedOutputPaths: parsedOwnedPaths,
    executionPolicy: parsedExecutionPolicy,
    targetRef: parsedTargetRef || null,
    workTypeId: workTypeId || null,
    workContextId: request.body.workContextId !== undefined && request.body.workContextId !== '' ? request.body.workContextId : null,
    workContextTargetId: request.body.workContextTargetId !== undefined && request.body.workContextTargetId !== '' ? request.body.workContextTargetId : null
  }, actorFromRequest(request), { delegated: delegatedFromRequest(request, 'created_from_ticket') });

  if (!result.ok) {
    return await renderTicketForm(result.error);
  }

  return reply.redirect('/tickets');
});

// ==================== WORK CONTEXT ROUTES ====================
// Product-layer grouping ONLY (r1.20). Management is gated by workContext:manage. Creating,
// updating, or archiving a Work Context creates NO ticket/run/schedule/target-op/workspace
// mutation and emits no execution event — it only writes the grouping store + an audit log.
function workContextManageGuard(request, reply) {
  if (!hasPermission(request.session.userId, 'workContext:manage')) {
    reply.code(403);
    return false;
  }
  return true;
}

function parseWorkContextPageOptions(query = {}) {
  const rawAfterId = query.afterId === undefined || query.afterId === '' ? 0 : Number(query.afterId);
  const rawLimit = query.limit === undefined || query.limit === '' ? 100 : Number(query.limit);
  if (!Number.isSafeInteger(rawAfterId) || rawAfterId < 0) return null;
  if (!Number.isSafeInteger(rawLimit) || rawLimit <= 0 || rawLimit > getRuntimeSchedulerCandidateLimit()) return null;
  return { afterId: rawAfterId, limit: rawLimit };
}

fastify.get('/api/work-contexts', { preHandler: fastify.requireAuth }, async (request, reply) => {
  if (!workContextManageGuard(request, reply)) return { error: 'Permission denied' };
  const options = parseWorkContextPageOptions(request.query || {});
  if (!options) { reply.code(400); return { error: 'afterId and limit must define a valid bounded page' }; }
  const page = await getWorkContextRepository().listWorkContexts(options);
  return { ok: true, ...page };
});

fastify.post('/api/work-contexts', { preHandler: fastify.requireAuth }, async (request, reply) => {
  if (!workContextManageGuard(request, reply)) return { error: 'Permission denied' };
  const parsed = validateWorkContextInput(request.body || {}, null);
  if (!parsed.ok) { reply.code(400); return { error: parsed.error }; }
  const changedBy = actorFromRequest(request).username || String(request.session.userId);
  const result = await getWorkContextRepository().createWorkContext({ value: parsed.value, changedBy });
  return { ok: true, workContext: result.workContext };
});

fastify.post('/api/work-contexts/:id', { preHandler: fastify.requireAuth }, async (request, reply) => {
  if (!workContextManageGuard(request, reply)) return { error: 'Permission denied' };
  const existing = await getWorkContextById(request.params.id);
  if (!existing) { reply.code(404); return { error: 'Work Context not found' }; }
  const parsed = validateWorkContextInput(request.body || {}, existing);
  if (!parsed.ok) { reply.code(400); return { error: parsed.error }; }
  const changedBy = actorFromRequest(request).username || String(request.session.userId);
  try {
    const result = await getWorkContextRepository().updateWorkContext({
      workContextId: existing.id,
      expectedRevision: existing.revision,
      value: parsed.value,
      changedBy
    });
    if (!result) { reply.code(404); return { error: 'Work Context not found' }; }
    return { ok: true, workContext: result.workContext };
  } catch (error) {
    if (error && error.code === 'OPTIMISTIC_CONCURRENCY_CONFLICT') {
      reply.code(409);
      return { error: 'Work Context changed concurrently; reload and retry' };
    }
    throw error;
  }
});

// Read-only visibility summary (r1.21) for one Work Context: bounded, deterministic, derived
// live from existing stores. It writes nothing and creates no new source of truth.
fastify.get('/api/work-contexts/:id/summary', { preHandler: fastify.requireAuth }, async (request, reply) => {
  if (!workContextManageGuard(request, reply)) return { error: 'Permission denied' };
  const ctx = await getWorkContextById(request.params.id);
  if (!ctx) { reply.code(404); return { error: 'Work Context not found' }; }
  return { ok: true, ...await buildWorkContextSummary(ctx) };
});

fastify.get('/work-contexts', { preHandler: fastify.requireAuth }, async (request, reply) => {
  if (!hasPermission(request.session.userId, 'workContext:manage')) {
    reply.code(403);
    return reply.view('error.ejs', viewData({ message: 'Access denied', user: request.user }, request.session.userId));
  }
  const options = parseWorkContextPageOptions(request.query || {});
  if (!options) {
    reply.code(400);
    return reply.view('error.ejs', viewData({ message: 'Invalid Work Context page cursor or limit', user: request.user }, request.session.userId));
  }
  const page = await getWorkContextRepository().listWorkContexts(options);
  const workContextIds = page.workContexts.map(ctx => ctx.id);
  const [ticketCountRows, templateCountRows] = workContextIds.length > 0
    ? await Promise.all([
      getRuntimeStateReadRepository().getWorkContextTicketCountsByIds({ workContextIds }),
      getProcessTemplateProjectionRepository().getProcessTemplateCountsByWorkContextIds({ workContextIds })
    ])
    : [[], []];
  const ticketCountByContext = new Map(ticketCountRows.map(row => [row.workContextId, row]));
  const templateCountByContext = new Map(templateCountRows.map(row => [row.workContextId, row]));
  const workContexts = page.workContexts.map(ctx => {
    const ticketCounts = ticketCountByContext.get(ctx.id) || {
      ticketCount: 0,
      openTicketCount: 0,
      blockedTicketCount: 0,
      unresolvedTriageCount: 0
    };
    const templateCounts = templateCountByContext.get(ctx.id) || { processTemplateCount: 0 };
    return {
      ...ctx,
      counts: {
        ...ticketCounts,
        processTemplateCount: templateCounts.processTemplateCount
      }
    };
  });
  return reply.view('work-contexts.ejs', viewData({
    user: request.user,
    workContexts,
    canManage: true,
    nextAfterId: page.nextAfterId,
    pageLimit: options.limit
  }, request.session.userId));
});

