fastify.post('/api/workspace/fixture', { preHandler: fastify.requireAuth }, async (request, reply) => {
  if (!hasPermission(request.session.userId, 'workspace:reset')) {
    reply.code(403);
    return { error: 'Permission denied' };
  }

  try {
    const fixtureId = String(request.body.fixtureId || '').trim();
    const fixture = WORKSPACE_FIXTURES.find(item => item.id === fixtureId);

    if (!fixture) {
      reply.code(400);
      return { error: 'Unknown workspace fixture' };
    }

    return await getWorkspaceMutationBoundaryRepository().withWorkspaceMutationBoundary({
      targetId: workspaceProvider.id
    }, async () => {
      const requestedBy = request.user ? request.user.username : String(request.session.userId);
      const preState = captureWorkspaceRootListing();
      applyWorkspaceFixture(fixtureId);
      const postState = captureWorkspaceRootListing();
      await appendSystemLog('workspace:fixture', `Workspace fixture reset: ${fixture.name}`, {
        operation: 'resetWorkspaceFixture',
        args: { fixtureId, workspaceRoot: workspaceProvider.root }
      }, {
        source: 'operator_workspace_fixture',
        requestedBy,
        preState,
        postState
      });

      return workspaceProvider.list('');
    });
  } catch (error) {
    reply.code(400);
    return { error: error.message || 'Workspace fixture reset failed' };
  }
});

// ==================== BROWSER ENVIRONMENT (OPERATOR) ROUTES ====================
// Operator-driven browser sessions mirror the run-side browser boundary: same
// Phase 1 operations, same target-scoped origin allowlist and limits (applied
// per operator session), and every session transition and operation lands in
// the diagnostic log with pre/post page state — the browser counterpart of
// workspace:operator_mutation.

const OPERATOR_BROWSER_SESSION_IDLE_MS = 10 * 60 * 1000;
const operatorBrowserSessions = new Map();
let operatorBrowserSessionSequence = 0;

function operatorBrowserError(code, message) {
  const error = new Error(message);
  error.code = code;
  error.failureKind = 'browser_error';
  return error;
}

async function captureOperatorBrowserPageState(entry) {
  try {
    const state = await entry.session.pageState();
    return {
      targetId: `browser:${entry.target.id}`,
      targetKind: 'browser',
      url: redactBrowserUrl(state.url),
      titleHash: hashContent(state.title || ''),
      capturedAt: new Date().toISOString()
    };
  } catch (_) {
    return null;
  }
}

function operatorBrowserSessionSummary(entry) {
  return {
    id: entry.id,
    target: entry.target,
    counters: { ...entry.counters },
    openedAt: entry.openedAt,
    lastOperationAt: entry.lastOperationAt,
    page: entry.lastKnownPage
  };
}

async function openOperatorBrowserSession(userId, requestedBy, targetId) {
  if (operatorBrowserSessions.has(userId)) {
    throw operatorBrowserError('BROWSER_SESSION_EXISTS', 'An operator browser session is already open; close it before opening another');
  }

  const target = (await getBrowserTargetById(targetId));
  if (!target || target.status !== 'active') {
    throw operatorBrowserError('BROWSER_TARGET_UNAVAILABLE', 'Browser target is unknown or inactive');
  }

  const snapshot = normalizeBrowserTargetSnapshot(target);
  const session = await createBrowserSession({
    allowedOrigins: snapshot.allowedOrigins,
    navTimeoutMs: browserLimit(snapshot, 'navTimeoutMs')
  });

  operatorBrowserSessionSequence += 1;
  const entry = {
    id: `operator-${operatorBrowserSessionSequence}-${Date.now()}`,
    userId,
    requestedBy,
    target: snapshot,
    session,
    counters: { actions: 0, navigations: 0, screenshots: 0, artifactSequence: 0 },
    openedAt: new Date().toISOString(),
    lastOperationAt: new Date().toISOString(),
    lastKnownPage: null,
    busy: false
  };
  operatorBrowserSessions.set(userId, entry);

  appendSystemLog('browser:operator_session_opened', `Operator browser session opened on target "${snapshot.name}" by ${requestedBy}`, {
    operation: 'openBrowserSession',
    args: { targetId: snapshot.id },
    targetId: `browser:${snapshot.id}`,
    targetKind: 'browser',
    targetScope: snapshot.allowedOrigins
  }, {
    source: 'operator_browser_api',
    requestedBy,
    sessionId: entry.id,
    browserTargetSnapshot: snapshot
  });

  return entry;
}

async function closeOperatorBrowserSession(userId, reason) {
  const entry = operatorBrowserSessions.get(userId);
  if (!entry) return null;
  operatorBrowserSessions.delete(userId);
  const postState = await captureOperatorBrowserPageState(entry);
  await entry.session.close().catch(() => {});

  appendSystemLog('browser:operator_session_closed', `Operator browser session on target "${entry.target.name}" closed: ${reason}`, {
    operation: 'closeBrowserSession',
    args: { reason },
    targetId: `browser:${entry.target.id}`,
    targetKind: 'browser',
    targetScope: entry.target.allowedOrigins
  }, {
    source: 'operator_browser_api',
    requestedBy: entry.requestedBy,
    sessionId: entry.id,
    reason,
    counters: { ...entry.counters },
    finalState: postState
  });

  return entry;
}

async function closeAllOperatorBrowserSessions(reason) {
  await Promise.all(
    [...operatorBrowserSessions.keys()].map(userId => closeOperatorBrowserSession(userId, reason).catch(() => {}))
  );
}

setInterval(() => {
  const now = Date.now();
  for (const [userId, entry] of operatorBrowserSessions) {
    if (!entry.busy && now - Date.parse(entry.lastOperationAt) > OPERATOR_BROWSER_SESSION_IDLE_MS) {
      void closeOperatorBrowserSession(userId, 'idle_timeout');
    }
  }
}, 60 * 1000).unref();

async function executeOperatorBrowserOperation(entry, operation, args = {}) {
  const target = entry.target;
  const startedAt = Date.now();

  const maxActions = browserLimit(target, 'maxActionsPerRun');
  if (entry.counters.actions + 1 > maxActions) {
    throw operatorBrowserError('BROWSER_ACTION_LIMIT_EXCEEDED', `Browser action limit of ${maxActions} exceeded for this session`);
  }
  if (operation === 'navigate' && entry.counters.navigations + 1 > browserLimit(target, 'maxNavigationsPerRun')) {
    throw operatorBrowserError('BROWSER_NAV_LIMIT_EXCEEDED', `Browser navigation limit of ${browserLimit(target, 'maxNavigationsPerRun')} exceeded for this session`);
  }
  if (operation === 'screenshot' && entry.counters.screenshots + 1 > browserLimit(target, 'maxScreenshotsPerRun')) {
    throw operatorBrowserError('BROWSER_ACTION_LIMIT_EXCEEDED', `Browser screenshot limit of ${browserLimit(target, 'maxScreenshotsPerRun')} exceeded for this session`);
  }

  entry.counters.actions += 1;
  const receipt = {
    operation,
    timestamp: createLogTimestamp(),
    metadata: {},
    partial: false,
    truncated: false,
    targetId: `browser:${target.id}`,
    targetKind: 'browser',
    targetScope: target.allowedOrigins,
    targetResourceId: null,
    resourceUrl: null
  };
  let result;

  if (operation === 'navigate') {
    if (typeof args.url !== 'string' || !args.url.trim()) {
      throw operatorBrowserError('BROWSER_ORIGIN_BLOCKED', 'navigate requires a non-empty URL');
    }
    entry.counters.navigations += 1;
    result = await entry.session.navigate(args.url.trim());
    receipt.resourceUrl = redactBrowserUrl(result.finalUrl || result.requestedUrl);
    receipt.metadata = {
      requestedUrl: redactBrowserUrl(result.requestedUrl),
      finalUrl: redactBrowserUrl(result.finalUrl),
      status: result.status,
      redirectChain: Array.isArray(result.redirectChain) ? result.redirectChain.map(redactBrowserUrl) : [],
      pageStateHash: hashContent(JSON.stringify({ url: result.finalUrl, title: result.title }))
    };
  } else if (operation === 'observe') {
    result = await entry.session.observe();
    const inventory = Array.isArray(result.elements) ? result.elements : [];
    receipt.resourceUrl = redactBrowserUrl(result.url);
    receipt.truncated = Boolean(result.truncated);
    receipt.metadata = {
      elementCount: inventory.length,
      pageStateHash: hashContent(JSON.stringify({ url: result.url, title: result.title, elements: inventory }))
    };
  } else if (operation === 'readPageText') {
    result = await entry.session.readPageText(browserLimit(target, 'maxPageTextBytes'));
    receipt.resourceUrl = redactBrowserUrl(result.url);
    receipt.truncated = Boolean(result.truncated);
    receipt.partial = Boolean(result.truncated);
    receipt.metadata = {
      bytes: result.bytes,
      fullBytes: result.fullBytes,
      contentHash: hashContent(result.text),
      pageStateHash: hashContent(JSON.stringify({ url: result.url, title: result.title, text: result.text }))
    };
  } else if (operation === 'screenshot') {
    entry.counters.screenshots += 1;
    entry.counters.artifactSequence += 1;
    const artifactDir = path.join(BROWSER_ARTIFACTS_DIR, entry.id);
    fs.mkdirSync(artifactDir, { recursive: true });
    const artifactPath = path.join(artifactDir, `shot-${entry.counters.artifactSequence}.png`);
    result = await entry.session.screenshot(artifactPath);
    const bytes = fs.readFileSync(artifactPath);
    const relativeArtifactPath = path.relative(ARTIFACT_ROOT, artifactPath);
    receipt.resourceUrl = redactBrowserUrl(result.url);
    receipt.metadata = {
      artifactPath: relativeArtifactPath,
      bytes: bytes.length,
      sha256: crypto.createHash('sha256').update(bytes).digest('hex'),
      pageStateHash: hashContent(JSON.stringify({ url: result.url, title: result.title }))
    };
    result = {
      url: result.url,
      title: result.title,
      artifactPath: relativeArtifactPath,
      bytes: bytes.length,
      sha256: receipt.metadata.sha256,
      dataUrl: `data:image/png;base64,${bytes.toString('base64')}`
    };
  } else if (operation === 'wait') {
    const forMs = Number(args.forMs);
    if (!Number.isFinite(forMs) || forMs < 0) {
      throw operatorBrowserError('BROWSER_TIMEOUT', 'wait requires a non-negative numeric forMs');
    }
    result = await entry.session.wait(forMs, browserLimit(target, 'waitTimeoutMsCap'));
    receipt.resourceUrl = redactBrowserUrl(result.url);
    receipt.truncated = Boolean(result.truncated);
    receipt.metadata = { requestedMs: result.requestedMs, waitedMs: result.waitedMs };
  } else {
    throw operatorBrowserError('BROWSER_OPERATION_UNSUPPORTED', `Unsupported browser operation: ${operation}`);
  }

  receipt.targetResourceId = receipt.resourceUrl;
  receipt.durationMs = Date.now() - startedAt;
  entry.lastKnownPage = { url: redactBrowserUrl(result.url || null), title: result.title || null };
  return { result, receipt };
}

function operatorBrowserSafeArgs(operation, args = {}) {
  if (operation === 'navigate') return { url: redactBrowserUrl(args.url) };
  if (operation === 'wait') return { forMs: args.forMs };
  return {};
}

async function operatorBrowserApi(request, reply, operationName, handler) {
  if (!hasPermission(request.session.userId, 'browser:operate')) {
    reply.code(403);
    return { error: 'Permission denied' };
  }

  try {
    return await handler(request.user ? request.user.username : String(request.session.userId));
  } catch (error) {
    reply.code(error.code === 'BROWSER_SESSION_EXISTS' || error.code === 'BROWSER_SESSION_BUSY' ? 409 : 400);
    return { error: error.message || `Browser ${operationName} failed`, code: error.code || null };
  }
}

fastify.get('/browser', { preHandler: fastify.requireAuth }, async (request, reply) => {
  if (!hasPermission(request.session.userId, 'browser:read')) {
    reply.code(403);
    return reply.view('error.ejs', viewData({
      message: 'Access denied',
      user: request.user
    }, request.session.userId));
  }

  const entry = operatorBrowserSessions.get(request.session.userId) || null;
  return reply.view('browser.ejs', viewData({
    user: request.user,
    browserEngineStatus: getEngineStatus(),
    browserTargets: (await readBrowserTargets())
      .filter(target => target && target.status === 'active')
      .map(normalizeBrowserTargetSnapshot),
    browserSession: entry ? operatorBrowserSessionSummary(entry) : null,
    canOperateBrowser: hasPermission(request.session.userId, 'browser:operate')
  }, request.session.userId));
});

fastify.get('/api/browser/session', { preHandler: fastify.requireAuth }, async (request, reply) => {
  if (!hasPermission(request.session.userId, 'browser:read')) {
    reply.code(403);
    return { error: 'Permission denied' };
  }
  const entry = operatorBrowserSessions.get(request.session.userId) || null;
  return { session: entry ? operatorBrowserSessionSummary(entry) : null, engine: getEngineStatus() };
});

fastify.post('/api/browser/session', { preHandler: fastify.requireAuth }, async (request, reply) => {
  return operatorBrowserApi(request, reply, 'session open', async requestedBy => {
    const entry = await openOperatorBrowserSession(
      request.session.userId,
      requestedBy,
      String(request.body && request.body.targetId || '').trim()
    );
    return { session: operatorBrowserSessionSummary(entry) };
  });
});

fastify.delete('/api/browser/session', { preHandler: fastify.requireAuth }, async (request, reply) => {
  return operatorBrowserApi(request, reply, 'session close', async () => {
    const entry = await closeOperatorBrowserSession(request.session.userId, 'operator_close');
    if (!entry) {
      throw operatorBrowserError('BROWSER_SESSION_LOST', 'No operator browser session is open');
    }
    return { closed: true };
  });
});

fastify.post('/api/browser/operation', { preHandler: fastify.requireAuth }, async (request, reply) => {
  return operatorBrowserApi(request, reply, 'operation', async requestedBy => {
    const entry = operatorBrowserSessions.get(request.session.userId);
    if (!entry) {
      throw operatorBrowserError('BROWSER_SESSION_LOST', 'No operator browser session is open; open a session first');
    }
    if (entry.busy) {
      throw operatorBrowserError('BROWSER_SESSION_BUSY', 'A browser operation is already in progress in this session');
    }

    const operation = String(request.body && request.body.operation || '').trim();
    const args = request.body && typeof request.body.args === 'object' && request.body.args ? request.body.args : {};
    if (!BROWSER_PHASE_ONE_OPERATIONS.includes(operation)) {
      throw operatorBrowserError('BROWSER_OPERATION_UNSUPPORTED', `Unsupported browser operation: ${operation}`);
    }

    entry.busy = true;
    const startedAt = Date.now();
    const preState = await captureOperatorBrowserPageState(entry);
    let outcome = null;
    let operationError = null;

    try {
      outcome = await executeOperatorBrowserOperation(entry, operation, args);
      return { ...outcome, session: operatorBrowserSessionSummary(entry) };
    } catch (error) {
      operationError = error;
      throw error;
    } finally {
      entry.busy = false;
      entry.lastOperationAt = new Date().toISOString();
      const postState = await captureOperatorBrowserPageState(entry);
      appendSystemLog('browser:operator_operation',
        operationError
          ? `Operator browser ${operation} by ${requestedBy} refused: ${operationError.message}`
          : `Operator browser ${operation} by ${requestedBy}`, {
        operation,
        args: operatorBrowserSafeArgs(operation, args),
        targetId: `browser:${entry.target.id}`,
        targetKind: 'browser',
        targetScope: entry.target.allowedOrigins
      }, {
        source: 'operator_browser_api',
        requestedBy,
        sessionId: entry.id,
        preState,
        postState,
        receipt: outcome ? sanitizeSnapshotValue(outcome.receipt) : null,
        error: operationError ? sanitizeLogMessage(operationError.message || String(operationError)) : null,
        errorCode: operationError ? operationError.code || null : null,
        durationMs: Date.now() - startedAt
      });
    }
  });
});

// ==================== ADMIN DASHBOARD ====================

fastify.get('/admin', { preHandler: fastify.requireAuth }, async (request, reply) => {
  if (!hasPermission(request.session.userId, 'user:read')) {
    reply.code(403);
    return reply.view('error.ejs', viewData({
      message: 'Access denied',
      user: request.user
    }, request.session.userId));
  }

  const [users, groups, memberships, agents, agentMemberships, allPermissions] = await Promise.all([
    listAccessUsers(),
    listAccessGroups(),
    listAccessUserMemberships(),
    listConfiguredAgentOptions(),
    listAgentGroupMembershipOptions(),
    listAccessPermissions()
  ]);
  const adminMutationTypes = new Set([
    'ticket:status_change',
    'ticket:rerun',
    'workspace:recovery',
    'admin:user_create',
    'admin:user_edit',
    'admin:user_delete',
    'admin:agent_create',
    'admin:agent_edit',
    'admin:agent_delete',
    'admin:group_create',
    'admin:group_edit',
    'admin:group_delete',
    'system:reset'
  ]);
  const recentAdminActivity = (await getDiagnosticLogRepository().listLogs({
    types: [...adminMutationTypes],
    order: 'desc',
    limit: 12
  })).logs;

  const usersWithGroups = users.map(account => {
    const accountGroupIds = Array.from(new Set(memberships
      .filter(membership => membership.userId === account.id)
      .map(membership => membership.groupId)));
    const accountGroups = groups.filter(group => accountGroupIds.includes(group.id));
    return { ...account, type: 'user', groups: accountGroups };
  });

  const agentsWithMaskedKeys = agents.map(agent => {
    const accountGroupIds = Array.from(new Set(agentMemberships
      .filter(membership => membership.agentId === agent.id)
      .map(membership => membership.groupId)));
    const accountGroups = groups.filter(group => accountGroupIds.includes(group.id));
    return { ...agent, type: 'agent', groups: accountGroups };
  });

  const accounts = [...usersWithGroups, ...agentsWithMaskedKeys].sort(
    (a, b) => new Date(b.createdAt) - new Date(a.createdAt)
  );

  const agentById = new Map(agents.map(agent => [agent.id, agent]));
  const membershipKeys = new Set(agentMemberships.map(membership =>
    `${membership.groupId}:${membership.agentId}`
  ));
  const groupsWithPermissions = groups.map(group => {
    const plannerAgent = group.plannerAgentId == null ? null : agentById.get(group.plannerAgentId) || null;
    return {
      ...group,
      plannerAgent,
      plannerIsCurrentMember: Boolean(plannerAgent && membershipKeys.has(`${group.id}:${plannerAgent.id}`))
    };
  });
  let workTypeCatalog = [];
  let workTypeCatalogError = null;
  try {
    workTypeCatalog = await readWorkTypes();
  } catch (error) {
    workTypeCatalogError = error.message || String(error);
  }

  return reply.view('admin/dashboard.ejs', viewData({
    users,
    agents,
    groups,
    membershipGroups: groups,
    accounts,
    groupsWithPermissions,
    recentAdminActivity,
    permissions: allPermissions,
    providers: PROVIDERS,
    models: MODELS,
    hasOpenAIApiKeyFallback: Boolean(String(process.env.OPENAI_API_KEY || '').trim()),
    hasOpenAIModelFallback: Boolean(String(process.env.OPENAI_MODEL || '').trim()),
    hasOllamaModelFallback: Boolean(String(process.env.OLLAMA_MODEL || '').trim()),
    ...(() => {
      const protectedPathsRead = readProtectedWorkspacePathsFromFile(PROTECTED_PATHS_FILE);
      return { protectedWorkspacePaths: protectedPathsRead.paths, protectedPathsFromConfig: protectedPathsRead.fromConfig };
    })(),
    sensitiveApplicationPaths: SENSITIVE_APPLICATION_PATHS,
    // A broken catalog must be visible on the dashboard, not a 500.
    workTypeCatalog,
    workTypeCatalogError,
    user: request.user,
    resetError: request.query.resetError || null,
    resetSuccess: request.query.resetSuccess || null
  }, request.session.userId));
});

fastify.post('/admin/debug-reset', {
  preHandler: fastify.requireAuth,
  config: { mutationAdmission: true }
}, async (request, reply) => {
  if (process.env.NODE_ENV === 'production') {
    reply.code(403);
    return 'Debug reset is disabled in production';
  }

  if (!hasPermission(request.session.userId, 'user:update')) {
    reply.code(403);
    return 'Permission denied';
  }

  const confirmation = String(request.body.confirmation || '').trim();
  if (confirmation !== 'RESET DEBUG DATA') {
    return reply.redirect('/admin?resetError=' + encodeURIComponent('Confirmation phrase did not match. Type RESET DEBUG DATA exactly.'));
  }

  try {
    await resetDebugData(request.user ? request.user.username : String(request.session.userId));
    return reply.redirect('/admin?resetSuccess=1');
  } catch (error) {
    return reply.redirect('/admin?resetError=' + encodeURIComponent(error.message || 'Reset failed'));
  }
});

// ==================== USER MANAGEMENT ====================

fastify.post('/admin/users', { preHandler: fastify.requireAuth }, async (request, reply) => {
  if (!hasPermission(request.session.userId, 'user:create')) {
    reply.code(403);
    return 'Permission denied';
  }

  const { accountType, username, password, groupIds, agentName, apiKey, model } = request.body;

  if (accountType === 'agent') {
    const provider = PROVIDERS.includes(request.body.provider) ? request.body.provider : 'openai';
    const hasApiKey = provider === 'ollama' || Boolean(apiKey && apiKey.trim()) || hasProviderApiKeyFallback(provider);
    const hasModel = Boolean(model && model.trim()) || hasProviderModelFallback(provider);

    if (!agentName || !hasApiKey || !hasModel) {
      return renderAdminUserForm(reply, request, {
        accountType: 'agent',
        error: provider === 'ollama'
          ? 'Agent name and Ollama model are required unless OLLAMA_MODEL is configured'
          : 'Agent name, API key, and model are required unless OpenAI env fallbacks are configured'
      });
    }

    if (await getConfiguredAgentRepository().getConfiguredAgentByName(agentName.trim())) {
      return renderAdminUserForm(reply, request, {
        accountType: 'agent',
        error: 'Agent name already exists'
      });
    }

    let normalizedGroupIds;
    try {
      normalizedGroupIds = await normalizeSubmittedGroupIdsForCatalog(groupIds);
    } catch (error) {
      return renderAdminUserForm(reply, request, {
        accountType: 'agent',
        error: error.message
      });
    }
    if (normalizedGroupIds.length > 0 && !hasPermission(request.session.userId, 'permission:assign')) {
      reply.code(403);
      return 'permission:assign is required to set group membership';
    }

    const changedBy = request.user ? request.user.username : String(request.session.userId);
    try {
      await getConfiguredAgentRepository().createConfiguredAgent({
        value: {
          name: agentName.trim(),
          type: 'agent',
          provider,
          model: model ? model.trim() : '',
          apiKey: apiKey ? apiKey.trim() : ''
        },
        groupIds: normalizedGroupIds,
        changedBy
      });
    } catch (error) {
      if (error && error.code === 'CONFIGURED_AGENT_NAME_CONFLICT') {
        return renderAdminUserForm(reply, request, { accountType: 'agent', error: 'Agent name already exists' });
      }
      throw error;
    }

    return reply.redirect('/admin');
  }

  if (!username || !password) {
    return renderAdminUserForm(reply, request, {
      accountType: 'user',
      error: 'Username and password are required'
    });
  }

  let normalizedGroupIds;
  try {
    normalizedGroupIds = await normalizeSubmittedGroupIdsForCatalog(groupIds);
  } catch (error) {
    return renderAdminUserForm(reply, request, {
      accountType: 'user',
      error: error.message
    });
  }
  if (normalizedGroupIds.length > 0 && !hasPermission(request.session.userId, 'permission:assign')) {
    reply.code(403);
    return 'permission:assign is required to set group membership';
  }

  const passwordHash = await argon2.hash(password);
  const changedBy = request.user ? request.user.username : String(request.session.userId);
  try {
    await getAccessCatalogRepository().createUser({
      value: {
        username: username.trim(),
        passwordHash
      },
      groupIds: normalizedGroupIds,
      changedBy
    });
  } catch (error) {
    if (error && error.code === 'USER_NAME_CONFLICT') {
      return renderAdminUserForm(reply, request, {
        accountType: 'user',
        error: 'Username already exists'
      });
    }
    throw error;
  }

  return reply.redirect('/admin');
});

fastify.get('/admin/users/:id/edit', { preHandler: fastify.requireAuth }, async (request, reply) => {
  if (!hasPermission(request.session.userId, 'user:update')) {
    reply.code(403);
    return reply.view('error.ejs', viewData({
      message: 'Access denied',
      user: request.user
    }, request.session.userId));
  }

  const accountId = parseInt(request.params.id);
  const accountType = request.query.type === 'agent' ? 'agent' : 'user';
  const foundAccount = accountType === 'agent'
    ? await getConfiguredAgentRepository().getConfiguredAgentById(accountId)
    : await getAccessCatalogRepository().getUserById(accountId);

  if (!foundAccount) {
    return reply.redirect('/admin');
  }

  const editAccount = accountType === 'user'
    ? { ...foundAccount, type: 'user' }
    : foundAccount;

  return renderAdminUserForm(reply, request, {
    editAccount,
    accountType
  });
});

fastify.post('/admin/users/:id', { preHandler: fastify.requireAuth }, async (request, reply) => {
  if (!hasPermission(request.session.userId, 'user:update')) {
    reply.code(403);
    return 'Permission denied';
  }

  const accountId = parseInt(request.params.id);
  const { accountType, username, password, groupIds, agentName, apiKey, model, revision } = request.body;
  const expectedRevision = parseInt(revision, 10);
  if (!Number.isSafeInteger(expectedRevision) || expectedRevision <= 0) {
    reply.code(400);
    return 'Invalid account revision';
  }

  if (accountType === 'agent') {
    const provider = PROVIDERS.includes(request.body.provider) ? request.body.provider : 'openai';
    const hasModel = Boolean(model && model.trim()) || hasProviderModelFallback(provider);
    const existingAgent = await getConfiguredAgentRepository().getConfiguredAgentById(accountId);
    if (!existingAgent) return reply.redirect('/admin');

    if (!agentName || !hasModel) {
      return renderAdminUserForm(reply, request, {
        editAccount: existingAgent,
        accountType: 'agent',
        error: provider === 'ollama'
          ? 'Agent name and Ollama model are required unless OLLAMA_MODEL is configured'
          : 'Agent name and model are required unless OPENAI_MODEL is configured'
      });
    }

    const duplicateAgent = await getConfiguredAgentRepository().getConfiguredAgentByName(agentName.trim());
    if (duplicateAgent && duplicateAgent.id !== accountId) {
      return renderAdminUserForm(reply, request, {
        editAccount: existingAgent,
        accountType: 'agent',
        error: 'Agent name already exists'
      });
    }

    let normalizedGroupIds;
    try {
      normalizedGroupIds = await normalizeSubmittedGroupIdsForCatalog(groupIds);
    } catch (error) {
      return renderAdminUserForm(reply, request, {
        editAccount: existingAgent,
        accountType: 'agent',
        error: error.message
      });
    }
    if (!sameValueSet(existingAgent.groupIds, normalizedGroupIds) && !hasPermission(request.session.userId, 'permission:assign')) {
      reply.code(403);
      return 'permission:assign is required to change group membership';
    }

    const changedBy = request.user ? request.user.username : String(request.session.userId);
    try {
      await getConfiguredAgentRepository().updateConfiguredAgent({
        agentId: accountId,
        expectedRevision,
        value: {
          ...existingAgent,
          name: agentName.trim(),
          provider,
          model: model ? model.trim() : '',
          apiKey: apiKey && apiKey.trim() ? apiKey.trim() : existingAgent.apiKey
        },
        groupIds: normalizedGroupIds,
        changedBy
      });
    } catch (error) {
      if (error && error.code === 'CONFIGURED_AGENT_NAME_CONFLICT') {
        return renderAdminUserForm(reply, request, { editAccount: existingAgent, accountType: 'agent', error: 'Agent name already exists' });
      }
      if (error && error.code === 'GROUP_PLANNER_MEMBERSHIP_REQUIRED') {
        return renderAdminUserForm(reply, request, { editAccount: existingAgent, accountType: 'agent', error: error.message });
      }
      if (error && error.code === 'OPTIMISTIC_CONCURRENCY_CONFLICT') {
        reply.code(409);
        return renderAdminUserForm(reply, request, { editAccount: error.current || existingAgent, accountType: 'agent', error: 'Agent changed concurrently; reload and retry' });
      }
      throw error;
    }

    return reply.redirect('/admin');
  }

  const existingUser = await getAccessCatalogRepository().getUserById(accountId);
  if (!existingUser) return reply.redirect('/admin');

  if (!username) {
    return renderAdminUserForm(reply, request, {
      editAccount: existingUser,
      accountType: 'user',
      error: 'Username is required'
    });
  }

  let normalizedGroupIds;
  try {
    normalizedGroupIds = await normalizeSubmittedGroupIdsForCatalog(groupIds);
  } catch (error) {
    return renderAdminUserForm(reply, request, {
      editAccount: existingUser,
      accountType: 'user',
      error: error.message
    });
  }
  if (!sameValueSet(existingUser.groupIds, normalizedGroupIds) && !hasPermission(request.session.userId, 'permission:assign')) {
    reply.code(403);
    return 'permission:assign is required to change group membership';
  }

  const changedBy = request.user ? request.user.username : String(request.session.userId);
  const passwordHash = password ? await argon2.hash(password) : existingUser.passwordHash;
  try {
    await getAccessCatalogRepository().updateUser({
      userId: accountId,
      expectedRevision,
      value: { username: username.trim(), passwordHash },
      groupIds: normalizedGroupIds,
      changedBy
    });
  } catch (error) {
    if (error && error.code === 'USER_NAME_CONFLICT') {
      return renderAdminUserForm(reply, request, { editAccount: existingUser, accountType: 'user', error: 'Username already exists' });
    }
    if (error && error.code === 'OPTIMISTIC_CONCURRENCY_CONFLICT') {
      reply.code(409);
      return renderAdminUserForm(reply, request, { editAccount: error.current || existingUser, accountType: 'user', error: 'User changed concurrently; reload and retry' });
    }
    throw error;
  }

  return reply.redirect('/admin');
});

fastify.post('/admin/users/:id/delete', { preHandler: fastify.requireAuth }, async (request, reply) => {
  if (!hasPermission(request.session.userId, 'user:delete')) {
    reply.code(403);
    return 'Permission denied';
  }

  const accountId = parseInt(request.params.id, 10);
  const { accountType, revision } = request.body;
  const expectedRevision = parseInt(revision, 10);
  if (!Number.isSafeInteger(accountId) || accountId <= 0 ||
      !Number.isSafeInteger(expectedRevision) || expectedRevision <= 0) {
    reply.code(400);
    return 'Invalid account identity or revision';
  }
  if (accountType !== 'agent' && accountId === request.session.userId) {
    return reply.redirect('/admin');
  }

  const changedBy = request.user ? request.user.username : String(request.session.userId);
  try {
    if (accountType === 'agent') {
      await getConfiguredAgentRepository().deleteConfiguredAgent({
        agentId: accountId,
        expectedRevision,
        changedBy
      });
    } else {
      await getAccessCatalogRepository().deleteUser({
        userId: accountId,
        expectedRevision,
        changedBy
      });
    }
  } catch (error) {
    if (error && error.code === 'OPTIMISTIC_CONCURRENCY_CONFLICT') {
      reply.code(409);
      return 'Account changed concurrently; reload and retry';
    }
    if (error && error.code === 'GROUP_PLANNER_MEMBERSHIP_REQUIRED') {
      reply.code(400);
      return error.message;
    }
    throw error;
  }

  return reply.redirect('/admin');
});

